import re

from moler.exceptions import CommandFailure
from moler.exceptions import ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand

__author__ = 'Miroslaw Wiacek'
__copyright__ = 'Copyright (C) 2021, Nokia'
__email__ = 'miroslaw.wiacek@nokia.com'


class Ne3sActivate(GenericEMSSIMCommand):
    """Ne3sActivate command class."""

    _default_prompt = r"(Discover\s+Operation\s+(SUCCEEDED|TIMED OUT|FAILED)"\
                      r"|\[NE3S\] Ne3s[a-zA-Z]+ flow (timeout|failure))"

    def __init__(self, connection, options=None, prompt=None, newline_chars=None, runner=None):
        """
        ne3s_activate command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Ne3sActivate, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.ret_required = False
        self._re_prompt = re.compile(self._get_prompt())

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = 'ne3s_activate'
        if self.options:
            cmd = f'{cmd} {self.options}'
        return cmd

    def _detect_start_of_cmd_output(self, line, is_full_line):
        if is_full_line and self._regex_helper.search(self._cmd_escaped, line) \
                and self._regex_helper.search_compiled(GenericEMSSIMCommand._re_start_command_id, line):
            self._cmd_output_started = True

    def is_end_of_cmd_output(self, line):
        """
        Check end of command output.

        :param line: Line from device.
        :return: None
        """
        if self._regex_helper.search_compiled(self._re_prompt, line):
            if 'SUCCEEDED' not in self._regex_helper.group(1):
                self.set_exception(CommandFailure(self, f"{self._regex_helper.group(1)} returned by EMSSIM"))
            return True
        return False

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
            except ParsingDone:
                pass
        return super(Ne3sActivate, self).on_new_line(line, is_full_line)

    _re_error = re.compile(r"ERROR:\s(?P<ERROR_MSG>.*)")

    def _parse_error(self, line):
        if self._regex_helper.search_compiled(Ne3sActivate._re_error, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR_MSG')}"))
            raise ParsingDone

    def _get_prompt(self):
        """
        ne3s_activate starts a flow, and based on passed options the end of the command output is different.

        :return: str
        """
        if isinstance(self.options, str):
            if "-pnp" in self.options or "-ac" in self.options:
                prompt = r"(Proxy\s+Command\s+ne3s_activate\s+(SUCCEEDED|TIMED\s+OUT|FAILED)|\[NE3S\] Ne3s[a-zA-Z]+ flow (timeout|failure))"
            else:
                prompt = Ne3sActivate._default_prompt
        else:
            prompt = Ne3sActivate._default_prompt

        return prompt


